def make_pair(H,W,top,left,oh,ow,inner_h,inner_w,outer_color,inner_color,pad):
    g=[[0]*W for _ in range(H)]
    for r in range(top,top+oh):
        for c in range(left,left+ow): g[r][c]=outer_color
    it=top+(oh-inner_h)//2; il=left+(ow-inner_w)//2
    for r in range(it,it+inner_h):
        for c in range(il,il+inner_w): g[r][c]=inner_color
    expected=[row[:] for row in g]
    for r in range(top-pad,top+oh+pad):
        for c in range(left-pad,left+ow+pad):
            if expected[r][c]==0: expected[r][c]=inner_color
    return g,expected
